import 'dart:io';

import 'package:yaml/yaml.dart';

/// The hosted version constraints an *existing* project already declares, and
/// a way to make a freshly templated workspace-package pubspec agree with them.
///
/// Real bug, found via a real project: the Workshop wrote a new split feature
/// package with NEAT's *current* template versions (freezed ^4.0.2, analyzer-14
/// toolchain — see ROADMAP §5u) into a project generated by an older NEAT
/// (freezed ^3.2.5, analyzer 12). A pub workspace resolves one version of
/// everything, so `pub get` failed outright and no build_runner pass could
/// run. A feature added to an existing project must follow the project's
/// stack, not NEAT's latest defaults.
abstract final class ProjectConstraints {
  /// Constraints from the root `pubspec.yaml`, then every
  /// `packages/*/pubspec.yaml` (root wins on conflicts). Only plain hosted
  /// constraints (`name: ^1.2.3`) are collected — `path:`/`sdk:`/`git:`
  /// dependencies are maps and are skipped.
  static Map<String, String> read(String projectPath) {
    final constraints = <String, String>{};
    final files = [
      File('$projectPath/pubspec.yaml'),
      ...() {
        final packages = Directory('$projectPath/packages');
        if (!packages.existsSync()) return const <File>[];
        final dirs = packages.listSync().whereType<Directory>().toList()
          ..sort((a, b) => a.path.compareTo(b.path));
        return [for (final d in dirs) File('${d.path}/pubspec.yaml')];
      }(),
    ];
    for (final file in files) {
      if (!file.existsSync()) continue;
      final Object? doc;
      try {
        doc = loadYaml(file.readAsStringSync());
      } on YamlException {
        continue;
      }
      if (doc is! YamlMap) continue;
      for (final section in const ['dependencies', 'dev_dependencies']) {
        final deps = doc[section];
        if (deps is! YamlMap) continue;
        deps.forEach((name, value) {
          if (name is String && value is String && value.isNotEmpty) {
            constraints.putIfAbsent(name, () => value);
          }
        });
      }
    }
    return constraints;
  }

  /// Rewrites the inline constraints under [pubspec]'s `dependencies:` and
  /// `dev_dependencies:` to [constraints] wherever the project already
  /// declares that package. Never touches `environment:` (a package's own
  /// `sdk:` lower bound is its language version, not a dependency), nor
  /// `path:`/`sdk:` dependencies, nor packages the project doesn't use yet.
  static String align(String pubspec, Map<String, String> constraints) {
    var section = '';
    final topLevel = RegExp(r'^([A-Za-z_]+):\s*$');
    final entry = RegExp(r'^  ([a-z0-9_]+): (\S.*)$');
    final lines = pubspec.split('\n');
    for (var i = 0; i < lines.length; i++) {
      final top = topLevel.firstMatch(lines[i]);
      if (top != null) {
        section = top.group(1)!;
        continue;
      }
      if (section != 'dependencies' && section != 'dev_dependencies') continue;
      final m = entry.firstMatch(lines[i]);
      if (m == null) continue;
      final project = constraints[m.group(1)!];
      if (project == null) continue;
      lines[i] = '  ${m.group(1)}: ${_yamlScalar(project)}';
    }
    return lines.join('\n');
  }

  // `^1.2.3` / `1.2.3` are safe bare; ranges (`>=1.0.0 <2.0.0`) need quoting.
  static String _yamlScalar(String constraint) =>
      RegExp(r'^\^?[0-9][0-9A-Za-z.+\-]*$').hasMatch(constraint)
      ? constraint
      : '"$constraint"';
}
